def box(x,y,w,h,t,sz=12,b=False,i=True):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="#fff" stroke="#111" stroke-width="1.5"/>'+T(x+w/2,y+h/2+4,t,sz,'middle',700 if b else 400,'#111')
def arr(x1,y1,x2,y2): return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="#c44" stroke-width="3"/><polygon points="{x2},{y2} {x2-(8 if x2>x1 else -8 if x2<x1 else 0)},{y2-(8 if y2>y1 else -8 if y2<y1 else 0)-4*(1 if x2!=x1 else 0)} {x2-(8 if x2>x1 else -8 if x2<x1 else 0)},{y2-(8 if y2>y1 else -8 if y2<y1 else 0)+4*(1 if x2!=x1 else 0)}" fill="#c44"/>'
